                ds.scoreHistory[i - 1] = r.score;
                rs = r;
            }
            ds.hardFail = rs.m.hard;
            var q = period - 1;
            ds.last = { roundScore: rs.score, hard: rs.m.hard };
            for (j = 0; j < KP.length; j++) { ds.last[KP[j]] = ds[KP[j] + 'History'][q]; }
            var score = this._composite(state);
            ds.performance = { overallScore: score };
            out.overallScore = score;
            out.score = score;
            out.roundScore = rs.score;
            for (j = 0; j < KP.length; j++) { out[KP[j]] = ds.last[KP[j]]; }
            if (period >= state.maxPeriods) { ds.finished = true; }
            var self = this;
            var nextP = (state.domainState && state.domainState.finished) ? state.currentPeriod : state.currentPeriod + 1;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state, nextP); }, 300);
            return out;
        }

        _flat(state, upto) {
            var d = (state && state.decisions) || {};
            var out = {};
            var p, k;
            for (p = 1; p <= upto; p++) {
                var r = d['round' + p];
                if (r) { for (k in r) { if (Object.prototype.hasOwnProperty.call(r, k)) { out[k] = r[k]; } } }
            }
            return out;
        }

        _active(dec, k, g) {
            if (this.ROUND_OF[g] <= k) {
                var v = dec[g];
                return (v === undefined || v === null) ? this.DEFAULTS[g] : v;
            }
            return this.REF[g];
        }

        _pol(a0, m) {
            var a = {};
            var j, g;
            for (j = 0; j < this.KEYS.length; j++) {
                g = this.KEYS[j];
                a[g] = (m >= this.START[g]) ? a0[g] : this.REF[g];
            }
            return a;
        }

        _psum(xs) {
            var t = 0.0, i;
            for (i = 0; i < xs.length; i++) { t = t + xs[i]; }
            return t;
        }

        _legs(mode, route, q, rise) {
            var c = this.C;
            var md = this.MODE[mode], rt = this.ROUTE[route];
            var l, iv, n, per;
            if (md[0] === 'pal') {
                n = (q > c.QMIN) ? q : c.QMIN;
                l = [md[2] * rt[0], md[3] / n, md[4], md[5] * rt[1] * rise, md[6], md[7] / n + md[8]];
                iv = 1.0;
            } else {
                per = (md[1] !== null) ? md[1] : ((q > c.QMIN) ? q : c.QMIN);
                l = [md[2] * rt[0] / per, md[3] / per, md[4] / per, md[5] * rt[1] * rise / per, md[6] / per,
                     (md[7] + md[8]) / per];
                iv = (md[1] !== null) ? md[1] / c.PAL : 1.0;
            }
            return { l: l, iv: iv, dmg: md[9] * rt[3], ot: rt[2] - md[10] - c.GAPOT * (iv - 1.0) };
        }

        _cover(insopt, ik, ctrl) {
            var c = this.C;
            var req = this.REQ[ik] || null;
            var imp = [c.IMP_COV, c.IMP_COV, 0.0];
            var z = [0.0, 0.0, 0.0];
            var cv, b;
            var own = (ik === 'exw' || ik === 'fob');
            if (insopt === 'todo') {
                cv = [c.DED, c.DED, c.DED];
                b = (ctrl === 1 || ik === 'ddp') ? cv : imp;
                return { cs: cv, cb: b, pr: ['A', c.INS_UP, 1.0], gp: z };
            }
            if (insopt === 'envio') {
                cv = [0.0, c.DED, 0.0];
                b = (ctrl === 1 || ik === 'ddp') ? cv : imp;
                return { cs: cv, cb: b, pr: ['A2', c.INS_UP, 0.50], gp: [(ik === 'cip') ? c.DED : 0.0, 0.0, 0.0] };
            }
            if (insopt === 'requerido') {
                if (req === null) { return { cs: z, cb: own ? imp : z, pr: null, gp: z }; }
                return { cs: z, cb: [(ik === 'cip') ? req[0][1] : 0.0, req[0][1], 0.0], pr: [req[1], c.INS_UP, req[2]], gp: z };
            }
            if (req === null) { return { cs: z, cb: own ? imp : z, pr: null, gp: z }; }
            return { cs: z, cb: z, pr: null, gp: [(ik === 'cip') ? req[0][1] : 0.0, req[0][1], 0.0] };
        }

        _month(a0, m, stop, q0) {
            var c = this.C;
            var a = this._pol(a0, m);
            var late13 = (stop === 1 && m >= c.MONTH13);
            var toExw = (late13 && this.PLAN[a.plan4][3] === 1);
            var ik = toExw ? 'exw' : a.incoterm1;
            var inc = this.INC[ik], doc = this.DOC[a.documentos3];
            var pl = late13 ? this.PLAN[a.plan4] : this.PLAN.spot;
            var pays = inc[0], ctrl = inc[3];
            var mode = (ctrl === 1) ? a.carga2 : this.IMP_DEFAULT[0];
            var route = (ctrl === 1) ? a.ruta2 : this.IMP_DEFAULT[1];
            var rise = 1.0;
            if (late13) {
                rise = 1.0 + c.RISE;
                if (ctrl === 1) { rise = rise * pl[0]; }
            }
            var q = q0;
            var lg = this._legs(mode, route, q, rise);
            var l = lg.l, iv = lg.iv, dmg = lg.dmg;
            var ot = lg.ot - doc[1] + ((ctrl === 1) ? pl[1] : 0.0);
            if (ik === 'exw') { ot = ot - c.EXW_OT; }
            if (ik === 'ddp') { ot = ot - c.DDP_OT; }
            var i;
            var seller = 0.0, bl = 0.0;
            for (i = 0; i < 6; i++) { seller = seller + l[i] * pays[i]; }
            for (i = 0; i < 6; i++) { bl = bl + l[i] * (1 - pays[i]); }
            var buyerLegs = bl * c.IMP_UP;
            if (ik === 'exw') { buyerLegs += c.EXW_EXTRA / Math.max(q, c.QMIN); }
            var cvr = this._cover(a.seguro3, ik, ctrl);
            var cs = cvr.cs, cb = cvr.cb, pr = cvr.pr, gp = cvr.gp;
            var baseVal = c.VAL + seller;
            var prem = 0.0;
            if (pr !== null) {
                var rate = (pr[0] === 'A') ? c.INS_A : ((pr[0] === 'A2') ? c.INS_A2 : c.INS_C);
                prem = rate * pr[1] * baseVal * pr[2];
            }
            var ddp = 0.0;
            if (pays[5] === 1) { ddp = c.TAXDDP * c.VAL + c.AGENT / Math.max(q, c.QMIN); }
            var sellerCost = seller + prem + ddp;
            var qt = a.cotizacion1;
            var price;
            if (qt === 'escandallo') { price = c.VAL + sellerCost * (1.0 + c.CONT); }
            else if (qt === 'margen') { price = c.VAL + sellerCost * (1.0 + c.MARK); }
            else if (qt === 'tarifa') { price = c.VAL + l[3] * pays[3]; }
            else { price = c.VAL + c.FIX; }
            var D = dmg * price;
            var sh = this.SRISK[ik];
            var sLoss = 0.0, bLoss = 0.0, gap = 0.0;
            for (i = 0; i < 3; i++) {
                var Li = D * this.LEGSHARE[i];
                sLoss += Li * sh[i] * (1.0 - cs[i]);
                bLoss += Li * (1.0 - sh[i]) * (1.0 - cb[i]);
                gap += Li * (1.0 - sh[i]) * gp[i];
            }
            bLoss -= gap;
            var duty = doc[0] * c.DUTY * (c.VAL + l[0] + l[1] + l[2] + l[3]);
            var sDuty = 0.0;
            if (pays[5] === 1) { sDuty = duty; duty = 0.0; }
            var late = (1.0 - ot) * c.LATE;
            var hold = iv / 2.0 * price * c.H_IMP / 12.0;
            var landed = price + buyerLegs + duty + bLoss + late + hold + doc[2];
            var marginP = price - c.COSTP - sellerCost - sLoss - gap - sDuty;
            var pad = price - c.VAL - sellerCost * (1.0 + c.CONT);
            var padf = (pad > 0.5 && sellerCost > 0) ? 1.0 - c.PADK * pad / sellerCost : 1.0;
            return { padf: padf, price: price, landed: landed, marginP: marginP, ot: ot, sLoss: sLoss + gap,
                     loss: sLoss + bLoss + gap, cpp: seller + buyerLegs / c.IMP_UP, fee: doc[3] / 12.0, mode: mode,
                     ctrl: ctrl, srisk: sh, insured: (pr !== null) || (ik === 'exw' || ik === 'fob'), ik: ik };
        }

        _volume(landed, ot, ref) {
            var c = this.C;
            var q = c.PAL * Math.pow(ref[0] / landed, c.E) * (1.0 + c.R * (ot - ref[1]));
            return this._clamp(q, 0.0, c.VMAX * c.PAL);
        }

        _solve(a, m, stop, ref) {
            var r = this._month(a, m, stop, this.C.PAL);
            r.q = this._volume(r.landed, r.ot, ref) * r.padf;
            return r;
        }

        _ga(a0, ref) {
            var c = this.C;
            var r = this._solve(a0, c.STOP_M, 1, ref);
            var q = r.q;
            var md = this.MODE[r.mode];
            var on = (md[1] === null || md[0] === 'pal') ? q : md[1];
            var V = on * r.price;
            var hit = (c.GA + c.PA) * V;
            var seaSeller = r.srisk[1] >= 1.0;
            var cri = this.CRI[a0.crisis4];
            var weeks = cri[0];
            if (weeks === 2.0 && !r.insured) { weeks = 4.0; }
            var unc = r.insured ? 0.0 : hit;
            var sUnc = (seaSeller || (r.ctrl === 1 && (r.ik === 'cip' || r.ik === 'cif'))) ? unc : 0.0;
            var margin = -sUnc;
            if (cri[1] === 1) { margin -= c.FINR * c.GA * V * 10.0 / 12.0; }
            var lost = q * this._clamp(weeks - 2.0, 0.0, 13.0) / c.WPM * c.LOSTF;
            if (cri[2] === 1) {
                margin -= on * c.AIR;
                lost = 0.0;
            }
            margin -= lost * r.marginP;
            return { margin: margin, loss: unc, sloss: sUnc, otlost: lost };
        }

        _event(dec, k) {
            var c = this.C;
            var self = this;
            var a = {};
            var j, m;
            for (j = 0; j < this.KEYS.length; j++) { a[this.KEYS[j]] = this._active(dec, k, this.KEYS[j]); }
            var b = this._month(this.REF, 1, 0, c.PAL);
            var ref = [b.landed, b.ot];
            var stop = (k >= 4) ? 1 : 0;
            var margin = 0.0, pal = 0.0, otw = 0.0, loss = 0.0, sloss = 0.0, cpp = 0.0, sales = 0.0;
            var bmargin = b.marginP * c.PAL;
            for (m = 1; m <= c.MONTHS; m++) {
                var r = this._solve(a, m, stop, ref);
                var q = r.q;
                margin += q * r.marginP - r.fee;
                pal += q; otw += q * r.ot; loss += q * r.loss; sloss += q * r.sLoss; cpp += q * r.cpp;
                sales += q * r.price;
            }
            if (stop === 1) {
                var g = this._ga(a, ref);
                margin += g.margin; loss += g.loss; sloss += g.sloss; otw -= g.otlost;
            }
            var net = margin - bmargin * c.MONTHS;
            var hard = 0;
            this.HARD.forEach(function(h2) { if (a[h2[0]] === h2[1] && k >= self.ROUND_OF[h2[0]]) { hard += 1; } });
            return { k: k, a: a, net: net, ontime: otw / pal, loss: loss, sloss: sloss, cpp: cpp / pal, pal: pal,
                     price: sales / pal, hard: hard };
        }

        _components(r) {
            var c = this.C;
            return [this._clamp((r.net - c.B_LO) / (c.B_HI - c.B_LO), 0, 1),
                    this._clamp((r.ontime - c.F_LO) / (c.F_HI - c.F_LO), 0, 1),
                    this._clamp((c.L_HI - r.loss) / (c.L_HI - c.L_LO), 0, 1)];
        }

        _roundScore(state, period) {
            var c = this.C;
            var m = this._event(this._flat(state, period), period);
            var comps = this._components(m);
            var w = [c.W_B, c.W_F, c.W_L];
            var tw = 0, num = 0, i;
            for (i = 0; i < 3; i++) { tw += w[i]; num = num + w[i] * comps[i]; }
            var score = this._clamp(100.0 * num / tw, 0, 100);
            if (m.hard > 0) {
                score = Math.min(score, c.CAP1 - c.CAP_STEP * (m.hard - 1));
