                if (panel) { panel.style.display = (!done && (i + 1) === period) ? '' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = done ? 'none' : ''; }
            this._syncControlsFromDecisions(state);
        }

        _fbKey(g, v) {
            var pfx = { incoterm1: 'in', cotizacion1: 'co', carga2: 'ca', ruta2: 'ru', seguro3: 'se', documentos3: 'do', crisis4: 'cr', plan4: 'pl' };
            var opts = {
                incoterm1: ['cip', 'fob', 'cif', 'ddp'],
                cotizacion1: ['escandallo', 'tarifa', 'fija', 'margen'],
                carga2: ['fcl20', 'lcl', 'fcl_mes', 'fcl40'],
                ruta2: ['directo', 'transbordo', 'bilbao', 'spot'],
                seguro3: ['todo', 'requerido', 'ninguno', 'envio'],
                documentos3: ['origen', 'habitual', 'tarde', 'subfactura'],
                crisis4: ['garantia', 'deposito', 'esperar', 'aereo'],
                plan4: ['contrato', 'spot', 'nvocc', 'exw']
            };
            var keys = {
                fb_in_cip: 1, fb_in_fob: 1, fb_in_cif: 1, fb_in_ddp: 1,
                fb_co_escandallo: 1, fb_co_tarifa: 1, fb_co_fija: 1, fb_co_margen: 1,
                fb_ca_fcl20: 1, fb_ca_lcl: 1, fb_ca_fcl_mes: 1, fb_ca_fcl40: 1,
                fb_ru_directo: 1, fb_ru_transbordo: 1, fb_ru_bilbao: 1, fb_ru_spot: 1,
                fb_se_todo: 1, fb_se_requerido: 1, fb_se_ninguno: 1, fb_se_envio: 1,
                fb_do_origen: 1, fb_do_habitual: 1, fb_do_tarde: 1, fb_do_subfactura: 1,
                fb_cr_garantia: 1, fb_cr_deposito: 1, fb_cr_esperar: 1, fb_cr_aereo: 1,
                fb_pl_contrato: 1, fb_pl_spot: 1, fb_pl_nvocc: 1, fb_pl_exw: 1
            };
            if (!opts[g] || opts[g].indexOf(v) < 0) { return 'fb_next'; }
