        getHistoryTableConfig() {
            var self = this;
            var money = function(v) { return self._fmtMoney(v); };
            var pct2 = function(v) { return self._fmtPct2(v); };
            var dec1 = function(v) { return self._fmtDec(v); };
            return [
                { key: 'results.margen', label: 'Margin improvement over 24 months', i18nKey: 'col_margen', formatter: money },
