                + '<div class="ej2754-cm-kpi">' + this._t('cm_kpi_perdidas') + ' <strong>' + this._fmtMoney(s.perdidas || 0) + '</strong></div>'
                + '<div class="ej2754-cm-kpi">' + this._t('cm_kpi_coste') + ' <strong>' + this._fmtMoney(s.coste || 0) + '</strong></div>'
                + '<div class="ej2754-cm-kpi">' + this._t('cm_kpi_palets') + ' <strong>' + this._fmtDec(s.palets || 0) + ' ' + this._t('txt_pallets') + '</strong></div>'
                + '<div class="ej2754-cm-kpi">' + this._t('cm_kpi_precio') + ' <strong>' + this._fmtMoney(s.precio || 0) + '</strong></div>'
